	  (function () {
	    var box = document.currentScript.parentNode;
	    var panel = box.querySelector('.kt-search-suggest');
	    var input = box.querySelector('#mkdocs-search-query');
	    var clear = box.querySelector('.kt-search-clear');

	    // Emptying the panel is what hides it (CSS :empty), so closing is just that.
	    function close () { while (panel.firstChild) { panel.removeChild(panel.firstChild); } }
	    // The button is only useful once there is something to clear.
	    function sync () { clear.hidden = !input.value; }

	    input.addEventListener('input', sync);
	    clear.addEventListener('click', function () {
	      input.value = '';
	      sync();
	      // search/main.js renders on keyup, which a programmatic clear never fires, so
	      // the panel has to be emptied here or the old hits would outlive the query.
	      close();
	      input.focus();
	    });

	    document.addEventListener('click', function (e) { if (!box.contains(e.target)) { close(); } });

	    // Escape has to be handled on keyUP, and on the document rather than the input.
	    // search/main.js binds doSearch to the field's keyup, so anything that closed the
	    // panel on keydown was undone microseconds later by that re-render — which is why
	    // Escape appeared to do nothing at all. Listening on the document means this runs
	    // after the field's own handler has already re-rendered, so closing sticks.
	    // What the panel looked like BEFORE that re-render is the interesting state, so it
	    // is captured on keydown: the usual two steps, Escape dismisses the suggestions,
	    // Escape again empties the box.
	    var panelWasOpen = false;
	    document.addEventListener('keydown', function (e) {
	      if (e.key === 'Escape') {
	        panelWasOpen = !!panel.firstChild;
	      }
	    });
	    document.addEventListener('keyup', function (e) {
	      if (e.key !== 'Escape') {
	        return;
	      }
	      // Only clear the field while it has focus — Escape elsewhere on the page is not ours.
	      if (!panelWasOpen && document.activeElement === input && input.value) {
	        input.value = '';
	        sync();
	      }
	      close();
	    });

	    sync();  // a ?q= deep link arrives with the field already filled
	  })();
